def decode_with_offset(n, offset):
    hex_str = hex(n)[2:]
    if len(hex_str) % 2 != 0:
        hex_str = '0' + hex_str

    bytes_list = [int(hex_str[i:i+2], 16) for i in range(0, len(hex_str), 2)]

    # Try with offset
    decoded = []
    for b in bytes_list:
        # Try different offsets
        for off in range(offset-5, offset+5):
            adjusted = (b + off) % 256
            if 65 <= adjusted <= 90 or 97 <= adjusted <= 122 or adjusted in [95, 32]:  # A-Z, a-z, underscore, space
                decoded.append(chr(adjusted))
                break

    return ''.join(decoded)

